def is_active_duel(entry: dict) -> bool:
    """True if this entry should be exposed to the AP world (item + locations).

    Excludes VRAINS gap rows (`name is None`) and tutorial slots
    (`tutorial=True` on each series's slot 1)."""
    return entry["name"] is not None and not entry.get("tutorial", False)
